function animate(env,el,p){
    var t=el.text, out="", n=Math.round(t.length*env.time);
    var cs = p.charset==1 ? "0123456789" : (p.charset==2 ? "!@#$%&*<>/?+=" : "ABCDEFGHIJKLMNOPQRSTUVWXYZ");
    for(var i=0;i<t.length;i++){
        var c=t.charAt(i);
        if( i<n || c==" " ){ out+=c; }
        else { var r=(AM.simplexNoise(i*3.7+env.absTime*9.0, p.seed)+1)/2; out+=cs.charAt(Math.floor(r*cs.length)%cs.length); }
    }
    el.text=out; return el;
}
